/**
 * Builds the example LOOPs for the dev page /lab/loop-words.
 *
 * Every example is generated by the engine through the MCP server's
 * generation path (generateViaEngine -> SequenceBuilder), then kept only if
 * the engine's class detector names exactly the requested type. On top of
 * that it must show its change plainly: every step spins at least one prop
 * with a pro or anti motion, and each step differs from its twin (a step that is its own
 * mirror image would look the same twice). The page's unit test checks the
 * written file again with the app's own detector.
 *
 * Run (from the repo or a worktree):
 *   node --conditions=development --import tsx scripts/loop-words-fixtures.ts
 * Writes src/routes/(public)/lab/loop-words/_data/loop-words-examples.json
 */
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { relationsForPair, loopDetectorClass } from "@tka/sequence-engine/loop";
import type { PairMotions } from "@tka/sequence-engine/loop";
import { ensureDataLoadedAsync } from "../mcp-server/src/shared/server-context.js";
import { generateViaEngine } from "../mcp-server/src/core/engine-generation-adapter.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const OUT = path.join(
  ROOT,
  "src/routes/(public)/lab/loop-words/_data/loop-words-examples.json"
);

type Kind =
  | "rotated"
  | "reflected"
  | "swapped"
  | "inverted"
  | "rewound"
  | "quartered";

interface Motion {
  motionType: string;
  startLocation: string;
  endLocation: string;
  rotationDirection: string;
  startOrientation: string;
  endOrientation: string;
  turns: number | "fl";
  plane?: string;
  prefloatMotionType?: string;
  prefloatRotationDirection?: string;
}

interface WireStep {
  letter: string;
  startPlacement: string;
  endPlacement: string;
  stepNumber: number;
  leftMotion: Motion;
  rightMotion: Motion;
}

const REQUEST: Record<
  Kind,
  { loopType: string; period: "halved" | "quartered"; passes: number; expect: string }
> = {
  rotated: { loopType: "rotated", period: "halved", passes: 2, expect: "rotated" },
  // The page calls it Reflected; the engine's left-right reflection is MIRRORED.
  reflected: { loopType: "mirrored", period: "halved", passes: 2, expect: "mirrored" },
  swapped: { loopType: "swapped", period: "halved", passes: 2, expect: "swapped" },
  inverted: { loopType: "inverted", period: "halved", passes: 2, expect: "inverted" },
  rewound: { loopType: "strict_rewound", period: "halved", passes: 2, expect: "rewound" },
  quartered: { loopType: "rotated", period: "quartered", passes: 4, expect: "rotated" },
};

const ATTEMPTS = Number(
  process.argv.find((a) => a.startsWith("--attempts="))?.slice(11) ?? 160
);

function pickMotion(m: Record<string, unknown>): Motion {
  const out: Motion = {
    motionType: String(m.motionType),
    startLocation: String(m.startLocation),
    endLocation: String(m.endLocation),
    rotationDirection: String(m.rotationDirection),
    startOrientation: String(m.startOrientation),
    endOrientation: String(m.endOrientation),
    turns: m.turns === "fl" ? "fl" : Number(m.turns ?? 0),
  };
  if (m.plane) out.plane = String(m.plane);
  if (m.prefloatMotionType) out.prefloatMotionType = String(m.prefloatMotionType);
  if (m.prefloatRotationDirection)
    out.prefloatRotationDirection = String(m.prefloatRotationDirection);
  return out;
}

const pair = (s: WireStep): PairMotions => ({
  left: {
    startLocation: s.leftMotion.startLocation,
    endLocation: s.leftMotion.endLocation,
    motionType: s.leftMotion.motionType,
  },
  right: {
    startLocation: s.rightMotion.startLocation,
    endLocation: s.rightMotion.endLocation,
    motionType: s.rightMotion.motionType,
  },
});

const isSpin = (m: Motion) => m.motionType === "pro" || m.motionType === "anti";

/** The step at 0-based index `k` of the first pass and its twin in pass `p`. */
function twinIndex(kind: Kind, k: number, n: number, p = 1): number {
  if (kind === "rewound") return 2 * n - 1 - k;
  return k + p * n;
}

/** Null when the example does not show its change plainly; else a score. */
function score(kind: Kind, steps: WireStep[], n: number): number | null {
  const passes = REQUEST[kind].passes;
  let s = 0;
  for (let k = 0; k < n; k++) {
    const a = steps[k]!;
    // Every step spins at least one prop, and nothing floats.
    if (!isSpin(a.leftMotion) && !isSpin(a.rightMotion)) return null;
    if (a.leftMotion.motionType === "float" || a.rightMotion.motionType === "float") return null;
    s += (isSpin(a.leftMotion) ? 1 : 0) + (isSpin(a.rightMotion) ? 1 : 0);
    for (let p = 1; p < passes; p++) {
      const b = steps[twinIndex(kind, k, n, p)]!;
      const prev = p === 1 ? a : steps[twinIndex(kind, k, n, p - 1)]!;
      const relations = relationsForPair(pair(prev), pair(b));
      // A twin that repeats its step would show no change.
      if (relations.some((r) => r.components.length === 0)) return null;
      if (kind !== "rewound" && kind !== "quartered") {
        const best = [...relations].sort((x, y) => x.priority - y.priority)[0];
        const want = kind === "reflected" ? "mirrored" : kind;
        if (!best || best.components.join() !== want) return null;
      }
    }
    if (a.leftMotion.motionType !== a.rightMotion.motionType) s += 3;
    if (a.leftMotion.turns === 0 && a.rightMotion.turns === 0) s += 1;
  }
  const types = new Set(steps.slice(0, n).flatMap((x) => [x.leftMotion.motionType, x.rightMotion.motionType]));
  if (kind === "inverted" && !(types.has("pro") && types.has("anti"))) return null;
  // An Inverted first pass where every prop spins was asked for and never
  // came (0 of 750 tries, 2026-11-16): the engine closes it with a still hand
  // or a dash. The page's Inverted line is worded to stay true to that.
  if (kind === "swapped" && !steps.slice(0, n).every((x) => x.leftMotion.motionType !== x.rightMotion.motionType)) {
    return null;
  }
  if (n === 3) s += 4;
  return s;
}

function detected(steps: WireStep[], start: WireStep): string | null {
  const raw = [start, ...steps].map((s) => ({
    letter: s.letter,
    startPlacement: s.startPlacement,
    endPlacement: s.endPlacement,
    stepNumber: s.stepNumber,
    motions: { left: s.leftMotion, right: s.rightMotion },
  }));
  // The engine's own step type carries more fields than the detector reads.
  const result = loopDetectorClass.detectLOOPType(raw as never);
  return result.loopType ? String(result.loopType) : null;
}

const pictographs = await ensureDataLoadedAsync("diamond" as never);
// --only=inverted,rewound rebuilds just those and keeps the rest of the file.
const ONLY = process.argv.find((a) => a.startsWith("--only="))?.slice(7).split(",");
const out: Record<string, unknown> = ONLY ? JSON.parse(readFileSync(OUT, "utf8")) : {};

for (const kind of (Object.keys(REQUEST) as Kind[]).filter((k) => !ONLY || ONLY.includes(k))) {
  const req = REQUEST[kind];
  let best: { score: number; wire: unknown } | null = null;
  let tried = 0;
  let matched = 0;
  for (const n of [3, 2, 4]) {
    for (let attempt = 0; attempt < ATTEMPTS; attempt++) {
      tried++;
      let result;
      try {
        result = generateViaEngine(
          {
            length: n * req.passes,
            gridMode: "diamond",
            level: attempt % 2 === 0 ? 1 : 2,
            constraintPreset: "smooth",
            loopType: req.loopType,
            period: req.period,
          },
          pictographs as never
        ).result;
      } catch {
        continue;
      }
      const all = result.steps.map((s) => ({
        letter: s.letter,
        startPlacement: s.startPlacement,
        endPlacement: s.endPlacement,
        stepNumber: s.stepNumber,
        leftMotion: pickMotion(s.leftMotion as never),
        rightMotion: pickMotion(s.rightMotion as never),
      }));
      const [start, ...steps] = all;
      if (!start || steps.length !== n * req.passes) continue;
      if (detected(steps, start) !== req.expect) continue;
      matched++;
      const sc = score(kind, steps, n);
      if (sc === null) continue;
      if (!best || sc > best.score) {
        best = {
          score: sc,
          wire: {
            word: steps.map((s) => s.letter).join(""),
            startPlacement: start.startPlacement,
            seedLength: n,
            steps,
          },
        };
      }
    }
    if (best) break;
  }
  console.log(
    `${kind}: ${matched}/${tried} detected as ${req.expect}; ` +
      (best ? `kept ${(best.wire as { word: string }).word} (score ${best.score})` : "NONE kept")
  );
  if (best) out[kind] = best.wire;
}

writeFileSync(OUT, JSON.stringify(out, null, 2) + "\n");
console.log(`wrote ${path.relative(ROOT, OUT)}`);
